'use client';

import {
  Field,
  FieldContent,
  FieldDescription,
  FieldError,
  FieldLabel,
} from '@/components/ui/field';
import { cn } from '@/lib/utils';
import { AnimatePresence, motion } from "motion/react";
import { ForwardedRef, forwardRef, useId } from "react";
import {
  BaseRendererProps,
  RenderCheckbox,
  RenderDatePicker,
  RenderTimePicker,
  RenderEditor,
  RenderInput,
  RenderSearchableSelect,
  RenderSelect,
  RenderSwitch,
  RenderTags,
  RenderTextarea,
  RenderMultiSelect,
  RenderDate
} from './superfield/field-renderers';
import {
  DatePickerFieldProps,
  TimePickerFieldProps,
  FileFieldProps,
  InputFieldProps,
  SearchableSelectFieldProps,
  SelectFieldProps,
  SelectOption,
  TagsFieldProps,
  TextareaFieldProps,
  MultiSelectFieldProps,
  LocationFieldProps
} from "./superfield/types";
import { RenderLocation } from "./superfield/field-renderers";

// Discriminated union of all field types
type SuperFieldProps =
  | InputFieldProps
  | TextareaFieldProps
  | FileFieldProps
  | SelectFieldProps
  // | CheckboxFieldProps
  | TagsFieldProps
  // | EditorFieldProps
  | SearchableSelectFieldProps
  | DatePickerFieldProps
  | TimePickerFieldProps
  // | SwitchFieldProps
  | MultiSelectFieldProps
  | LocationFieldProps;

const renderers: Record<string, React.ElementType> = {
  'select': RenderSelect,
  'searchable-select': RenderSearchableSelect,
  'multi-select': RenderMultiSelect,
  'textarea': RenderTextarea,
  'date': RenderDate,
  // 'checkbox': RenderCheckbox,
  // 'switch': RenderSwitch,
  'tags': RenderTags,
  // 'editor': RenderEditor,
  'datepicker': RenderDatePicker,
  'timepicker': RenderTimePicker,
  'location': RenderLocation,
  'file': RenderInput,
  'default': RenderInput
};

/**
 * SuperField Component
 * A high-level abstraction for form fields, combining Label, Input/Textarea/Select, and Error handling.
 * Supports InputGroups (prefixes/suffixes) and is fully accessible.
 *
 * Supported field types:
 * - text, email, password, number, tel, url, search, date, time, datetime-local
 * - textarea
 * - file
 * - select (with options array or children)
 * - searchable-select
 * - tags
 * - editor
 * - checkbox
 * - datepicker
 * - switch
 *
 * @example
 * // Searchable Select
 * <SuperField
 *   type="searchable-select"
 *   label="Framework"
 *   options={[
 *     { label: "React", value: "react" },
 *     { label: "Vue", value: "vue" }
 *   ]}
 * />
 *
 * @example
 * // Date Picker
 * <SuperField
 *   type="datepicker"
 *   label="Start Date"
 *   value={new Date()}
 *   onChange={(date) => console.log(date)}
 *   placeholder="Select a date"
 * />
 *
 * @example
 * // Tags
 * <SuperField
 *   type="tags"
 *   label="Skills"
 *   value={['React', 'Next.js']}
 *   onChange={(tags) => console.log(tags)}
 * />
 */
export const SuperField = forwardRef<
  HTMLInputElement | HTMLTextAreaElement,
  SuperFieldProps
>( ( props, ref ) => {
  const {
    label,
    description,
    error,
    errors,
    required,
    disabled,
    className,
    fieldClassName,
    labelClassName,
    type,
    prefix,
    suffix,
    prefixAlign = 'inline-start',
    suffixAlign = 'inline-end',
    headerExtra,
    id,
    ...rest
  } = props;

  const generatedId = useId();
  const fieldId = id || generatedId;
  const hasInputGroup = !!( prefix || suffix ) && type !== 'file';

  const ariaConfig = {
    'aria-invalid': !!( error || errors?.length ),
    'aria-describedby':
      description || error || errors?.length
        ? `${ fieldId }-description ${ fieldId }-error`
        : undefined,
  };

  const isCheckable = ( type as string ) === 'checkbox' || ( type as string ) === 'switch';
  const Renderer = renderers[ type ] || renderers[ 'default' ];

  const baseProps: BaseRendererProps = {
    fieldId,
    required,
    disabled,
    ariaConfig,
    fieldClassName,
    hasInputGroup,
    prefix,
    suffix,
    prefixAlign,
    suffixAlign
  };

  const renderControl = () => (
    <Renderer
      props={ props }
      base={ baseProps }
      ref={ ref as ForwardedRef<any> }
    />
  );

  return (
    <Field
      className={ cn( className, ) }
      data-disabled={ disabled }
      data-invalid={ !!( error || errors?.length ) }
      orientation={ isCheckable ? 'horizontal' : 'vertical' }
    >
      { isCheckable ? (
        <>
          { renderControl() }
          <FieldContent>
            { label && (
              <FieldLabel htmlFor={ fieldId } className={ cn( "cursor-pointer", labelClassName ) }>
                { label }
                { required && <span className='text-destructive -ml-1'>*</span> }
              </FieldLabel>
            ) }
            { description && (
              <FieldDescription id={ `${ fieldId }-description` }>
                { description }
              </FieldDescription>
            ) }
            <AnimatePresence mode='wait'>
              { ( error || errors ) && (
                <motion.div initial={ { opacity: 0, height: 0 } } animate={ { opacity: 1, height: "auto" } } exit={ { opacity: 0, height: 0 } }>
                  <FieldError id={ `${ fieldId }-error` } errors={ errors } className="font-regular">
                    { error }
                  </FieldError>
                </motion.div>
              ) }
            </AnimatePresence>
          </FieldContent>
        </>
      ) : (
        <>
          { label && (
            <div className="flex items-center justify-between">
              <FieldLabel htmlFor={ fieldId } className={ labelClassName }>
                { label }
                { required && <span className='text-destructive -ml-1'>*</span> }
              </FieldLabel>
              { headerExtra }
            </div>
          ) }
          { description && (
            <FieldDescription id={ `${ fieldId }-description` }>
              { description }
            </FieldDescription>
          ) }
          { renderControl() }
          <AnimatePresence mode='wait'>
            { ( error || errors ) && (
              <motion.div initial={ { opacity: 0, height: 0 } } animate={ { opacity: 1, height: "auto" } } exit={ { opacity: 0, height: 0 } }>
                <FieldError id={ `${ fieldId }-error` } errors={ errors } className="font-regular">
                  { error }
                </FieldError>
              </motion.div>
            ) }
          </AnimatePresence>
        </>
      ) }
    </Field>
  );
} );

SuperField.displayName = 'SuperField';

// Export types for external use
export type { SelectOption };

'use client';

import { useEffect, useRef } from 'react';
import Quill from 'quill';
import 'quill/dist/quill.snow.css';
import { cn } from '@/lib/utils';

export type QuillToolbarConfig = ( string[] | Record<string, any>[] | string )[];

interface QuillEditorProps {
  value?: string;
  onChange?: ( value: string ) => void;
  onBlur?: () => void;
  placeholder?: string;
  className?: string;
  disabled?: boolean;
  toolbar?: QuillToolbarConfig;
}

const defaultToolbar: QuillToolbarConfig = [
  [ 'bold', 'italic', 'underline', 'strike' ],
  [ { 'list': 'ordered' }, { 'list': 'bullet' } ],
  [ 'clean' ]
];

export function QuillEditor( { value, onChange, onBlur, placeholder, className, disabled, toolbar = defaultToolbar }: QuillEditorProps ) {
  const containerRef = useRef<HTMLDivElement>( null );
  const quillRef = useRef<Quill | null>( null );
  const isInternalChange = useRef( false );
  const lastValueRef = useRef( value );
  const onBlurRef = useRef( onBlur );

  useEffect( () => {
    onBlurRef.current = onBlur;
  }, [ onBlur ] );

  useEffect( () => {
    if ( !containerRef.current ) return;

    if ( !quillRef.current ) {
      const quill = new Quill( containerRef.current, {
        theme: 'snow',
        placeholder: placeholder,
        modules: {
          toolbar: toolbar
        },
        readOnly: disabled
      } );

      quillRef.current = quill;

      // Set initial value if provided (important for persisted form state)
      if ( value && value !== '<p><br></p>' ) {
        quill.root.innerHTML = value;
        lastValueRef.current = value;
      }

      quill.on( 'text-change', () => {
        if ( onChange ) {
          isInternalChange.current = true;
          // Send HTML content
          const content = quill.root.innerHTML;
          lastValueRef.current = content;
          onChange( content );
          isInternalChange.current = false;
        }
      } );

      quill.on( 'selection-change', ( range, oldRange ) => {
        if ( range === null && oldRange !== null ) {
          onBlurRef.current?.();
        }
      } );
    }

    return () => {
      // Cleanup if needed
    };
  }, [] ); // Init once

  // Handle external value changes
  useEffect( () => {
    const quill = quillRef.current;
    console.debug( '[QuillEditor] value prop changed:', value, 'lastValueRef:', lastValueRef.current, 'quillReady:', !!quill );
    if ( quill && value !== undefined && value !== lastValueRef.current && !isInternalChange.current ) {
      // Prevent stale props from overwriting local state while user is typing
      if ( quill.hasFocus() ) {
        console.debug( '[QuillEditor] Quill has focus, skipping update' );
        return;
      }

      if ( value !== quill.root.innerHTML ) {
        console.debug( '[QuillEditor] Updating quill content from prop' );
        quill.root.innerHTML = value;
      }
      lastValueRef.current = value;
    }
  }, [ value ] );

  // Handle disabled state change
  useEffect( () => {
    if ( quillRef.current ) {
      quillRef.current.enable( !disabled );
    }
  }, [ disabled ] );

  return (
    <div className={ cn(
      "quill-editor-wrapper flex flex-col rounded-md border border-input bg-transparent shadow-xs transition-[color,box-shadow]",
      "focus-within:ring-[3px] focus-within:ring-ring/50 focus-within:border-ring",
      "dark:bg-input/30",
      className
    ) }>
      <div ref={ containerRef } className="min-h-[150px] text-foreground flex-1" />
      <style jsx global>{ `
        .quill-editor-wrapper .ql-toolbar.ql-snow {
          border: none;
          border-bottom: 1px solid hsl(var(--input));
          background-color: transparent;
          padding: 8px;
          font-family: var(--font-secondary), ui-sans-serif, system-ui, sans-serif;
        }
        .quill-editor-wrapper .ql-container.ql-snow {
          border: none;
          font-family: var(--font-secondary), ui-sans-serif, system-ui, sans-serif;
          display: flex;
          flex-direction: column;
          flex: 1;
        }
        .quill-editor-wrapper .ql-editor {
          min-height: 150px;
          flex: 1;
          font-family: var(--font-secondary), ui-sans-serif, system-ui, sans-serif;
          font-size: 0.875rem;
          line-height: 1.5;
          font-weight: 400;
          padding: 0.625rem 0.75rem;
        }
        .quill-editor-wrapper .ql-editor p {
          font-weight: 300;
        }
        .quill-editor-wrapper .ql-editor p,
        .quill-editor-wrapper .ql-editor li,
        .quill-editor-wrapper .ql-editor span {
          font-family: inherit;
        }
        .quill-editor-wrapper .ql-editor.ql-blank::before {
          color: hsl(var(--muted-foreground));
          font-style: normal;
          font-family: var(--font-secondary), ui-sans-serif, system-ui, sans-serif;
          left: 0.75rem;
          right: 0.75rem;
        }
          .quill-editor .ql-blank p {
            font-weight: 300;
          }
      `}</style>
    </div>
  );
}

"use client";

import * as React from "react";
import { format } from "date-fns";
import { Calendar as CalendarIcon } from "lucide-react";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

export interface CalendarInputProps {
  id?: string;
  value?: string;
  onChange?: ( value: string ) => void;
  onBlur?: React.FocusEventHandler<HTMLButtonElement>;
  placeholder?: string;
  disabled?: boolean;
  required?: boolean;
  className?: string;
  "aria-invalid"?: boolean;
  "aria-describedby"?: string;
}

export function CalendarInput( {
  id,
  value,
  onChange,
  onBlur,
  placeholder = "Pick a date",
  disabled,
  required,
  className,
  ...ariaProps
}: CalendarInputProps ) {
  const [ open, setOpen ] = React.useState( false );

  // Convert string value to Date object
  const selectedDate = value ? new Date( value ) : undefined;

  const handleSelect = ( date: Date | undefined ) => {
    if ( date ) {
      // Format as YYYY-MM-DD for form compatibility
      const formattedDate = format( date, "yyyy-MM-dd" );
      onChange?.( formattedDate );
    } else {
      onChange?.( "" );
    }
    setOpen( false );
  };

  return (
    <Popover open={ open } onOpenChange={ setOpen }>
      <PopoverTrigger>
        <Button
          id={ id }
          variant="outline"
          size={ 'lg' }
          className={ cn(
            "w-full justify-start text-left font-normal",
            !value && "text-muted-foreground",
            className
          ) }
          disabled={ disabled }
          onBlur={ onBlur }
          { ...ariaProps }
        >
          <CalendarIcon className="mr-2 size-4" strokeWidth={ 1 } />
          { value ? format( new Date( value ), "PPP" ) : <span>{ placeholder }</span> }
        </Button>
      </PopoverTrigger>
      <PopoverContent className="vega-form dark w-auto p-0" align="start">
        <Calendar
          mode="single"
          selected={ selectedDate }
          onSelect={ handleSelect }
          autoFocus
        />
      </PopoverContent>
    </Popover>
  );
}

import { AriaAttributes, KeyboardEvent, useEffect, useRef, useState } from "react";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";
import { HugeiconsIcon } from "@hugeicons/react";
import { Calendar01Icon } from "@hugeicons/core-free-icons";
import { BaseFieldProps } from "./base-types";
import { cn } from "@/lib/utils";

export interface DatePickerInputProps {
  id?: string;
  name?: string;
  value?: Date | string;
  onChange?: ( value: Date | undefined ) => void;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
  ariaConfig?: AriaAttributes;
  dateFormat?: Intl.DateTimeFormatOptions;
  locale?: string;
  minDate?: Date;
  maxDate?: Date;
  onBlur?: () => void;
}

export interface DatePickerFieldProps extends BaseFieldProps, Omit<DatePickerInputProps, keyof BaseFieldProps> {
  type: 'datepicker';
}

const DEFAULT_DATE_FORMAT: Intl.DateTimeFormatOptions = { day: "2-digit", month: "long", year: "numeric" };

const normalizeDate = ( d: Date | string | undefined ): Date | undefined => {
  if ( !d ) return undefined;
  if ( d instanceof Date ) return d;
  if ( typeof d === 'string' ) {
    const parsed = new Date( d );
    return isNaN( parsed.getTime() ) ? undefined : parsed;
  }
  return undefined;
};

function formatDateValue( date: Date | undefined, format: Intl.DateTimeFormatOptions, loc: string ) {
  if ( !date || !( date instanceof Date ) || isNaN( date.getTime() ) ) return "";
  return date.toLocaleDateString( loc, format );
}

function isValidDate( date: Date | undefined ) {
  if ( !date ) return false;
  return !isNaN( date.getTime() );
}

function startOfDay( date: Date ): Date {
  return new Date( date.getFullYear(), date.getMonth(), date.getDate() );
}

export const DatePickerInput = ( {
  id,
  value,
  onChange,
  placeholder,
  disabled,
  className,
  ariaConfig,
  dateFormat = DEFAULT_DATE_FORMAT,
  locale = "en-US",
  minDate,
  maxDate,
  onBlur,
}: DatePickerInputProps ) => {

  const normalizedValue = normalizeDate( value as Date | string | undefined );

  const [ open, setOpen ] = useState( false );
  const [ month, setMonth ] = useState<Date | undefined>( normalizedValue || new Date() );
  const [ inputValue, setInputValue ] = useState( normalizedValue ? formatDateValue( normalizedValue, dateFormat, locale ) : "" );
  const lastEmittedDateRef = useRef<Date | undefined>( undefined );

  // Sync input value when external value changes
  useEffect( () => {
    const normalized = normalizeDate( value as Date | string | undefined );
    if ( normalized ) {
      queueMicrotask( () => {
        setMonth( normalized );
        const isFromTyping = lastEmittedDateRef.current && lastEmittedDateRef.current.getTime() === normalized.getTime();
        if ( !isFromTyping ) {
          setInputValue( formatDateValue( normalized, dateFormat, locale ) );
        }
      } );
    } else {
      queueMicrotask( () => setInputValue( "" ) );
    }
  }, [ value, dateFormat, locale ] );

  const handleInputChange = ( e: React.ChangeEvent<HTMLInputElement> ) => {
    const newValue = e.target.value;
    setInputValue( newValue );
    const date = new Date( newValue );
    const beforeMinimum = minDate && startOfDay( date ) < startOfDay( minDate );
    const afterMaximum = maxDate && startOfDay( date ) > startOfDay( maxDate );
    if ( isValidDate( date ) && !beforeMinimum && !afterMaximum ) {
      lastEmittedDateRef.current = date;
      onChange?.( date );
      setMonth( date );
    }
  };

  const handleBlur = () => {
    if ( normalizedValue ) {
      setInputValue( formatDateValue( normalizedValue, dateFormat, locale ) );
    }
    lastEmittedDateRef.current = undefined;
    onBlur?.();
  };

  const handleKeyDown = ( e: KeyboardEvent<HTMLInputElement> ) => {
    if ( e.key === "ArrowDown" || e.key === "Enter" ) {
      e.preventDefault();
      setOpen( true );
    }
  };

  const handleSelect = ( date: Date | undefined ) => {
    if ( date && minDate && startOfDay( date ) < startOfDay( minDate ) ) return;
    if ( date && maxDate && startOfDay( date ) > startOfDay( maxDate ) ) return;
    onChange?.( date );
    if ( date ) {
      setInputValue( formatDateValue( date, dateFormat, locale ) );
    }
    setOpen( false );
    lastEmittedDateRef.current = undefined;
  };

  return (
    <InputGroup className={ className }>
      <InputGroupInput
        id={ id }
        value={ inputValue }
        placeholder={ placeholder || "Select date..." }
        onChange={ handleInputChange }
        onKeyDown={ handleKeyDown }
        onBlur={ handleBlur }
        disabled={ disabled }
        { ...ariaConfig }
      />
      <InputGroupAddon align="inline-end">
        <Popover open={ open } onOpenChange={ setOpen }>
          <PopoverTrigger
            render={
              <InputGroupButton
                variant="ghost"
                size="icon-xs"
                aria-label="Select date"
                disabled={ disabled }
                type="button"
              >
                <HugeiconsIcon icon={ Calendar01Icon } strokeWidth={ 2 } />
                <span className="sr-only">Select date</span>
              </InputGroupButton>
            }
          />
          <PopoverContent
            className="vega-form dark w-auto overflow-hidden p-0"
            align="end"
            alignOffset={ -4 }
            sideOffset={ 10 }
          >
            <div
              onClick={ ( e ) => e.stopPropagation() }
              onMouseDown={ ( e ) => e.stopPropagation() }
            >
              <Calendar
                mode='single'
                selected={ normalizedValue }
                month={ month }
                onMonthChange={ setMonth }
                onSelect={ handleSelect }
                captionLayout="dropdown"
                disabled={ ( date ) => {
                  if ( minDate && startOfDay( date ) < startOfDay( minDate ) ) return true;
                  if ( maxDate && startOfDay( date ) > startOfDay( maxDate ) ) return true;
                  return false;
                } }
              />
            </div>
          </PopoverContent>
        </Popover>
      </InputGroupAddon>
    </InputGroup>
  );
};

import { ReactNode, useMemo, ForwardedRef, ComponentProps } from 'react';
import { cn } from '@/lib/utils';
import { Checkbox } from "@/components/ui/checkbox";
import { Switch } from "@/components/ui/switch";
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { InputGroup, InputGroupInput, InputGroupTextarea, InputGroupAddon, InputGroupText } from '@/components/ui/input-group';
import { SearchableSelect } from './searchable-select';
import { TagsInput } from './tags-input';
import { CalendarInput } from './calendar-input';
import { DatePickerInput } from './date-picker-input';
import { TimePickerInput } from './time-picker-input';
import {
  SelectFieldProps,
  SearchableSelectFieldProps,
  EditorFieldProps,
  TagsFieldProps,
  DatePickerFieldProps,
  TimePickerFieldProps,
  InputFieldProps,
  TextareaFieldProps,
  FileFieldProps,
  MultiSelectFieldProps
} from './types';

function SuperFieldInputGroupSelect({
  className,
  ...props
}: ComponentProps<typeof SelectTrigger>) {
  return (
    <SelectTrigger
      data-slot="input-group-control"
      className={cn(
        "flex-1 rounded-none border-0 bg-transparent shadow-none ring-0 focus-visible:ring-0 aria-invalid:ring-0 dark:bg-transparent",
        className
      )}
      {...props}
    />
  );
}
import { MultiSelectInput } from './multi-select-input';
import dynamic from 'next/dynamic';

const QuillEditor = dynamic( () => import( '@/components/ui/quill-editor' ).then( mod => mod.QuillEditor ), {
  ssr: false,
  loading: () => <div className="h-[150px] w-full rounded-md border border-input bg-transparent animate-pulse" />
} );


export interface BaseRendererProps {
  fieldId: string;
  required?: boolean;
  disabled?: boolean;
  ariaConfig: object;
  fieldClassName?: string;
  hasInputGroup: boolean;
  prefix?: ReactNode;
  suffix?: ReactNode;
  prefixAlign?: 'inline-start' | 'block-start';
  suffixAlign?: 'inline-end' | 'block-end';
}

const renderAddon = (
  content: ReactNode,
  align: 'inline-start' | 'block-start' | 'inline-end' | 'block-end'
) => {
  if ( !content ) return null;
  return (
    <InputGroupAddon align={ align }>
      { typeof content === 'string' ? (
        <InputGroupText>{ content }</InputGroupText>
      ) : (
        content
      ) }
    </InputGroupAddon>
  );
};

export const RenderInput = ( {
  props,
  base,
  ref
}: {
  props: InputFieldProps | FileFieldProps;
  base: BaseRendererProps;
  ref?: ForwardedRef<HTMLInputElement>;
} ) => {
  const {
    type,
    label,
    description,
    error,
    errors,
    fieldClassName,
    labelClassName,
    prefix,
    suffix,
    prefixAlign,
    suffixAlign,
    headerExtra,
    className,
    ...rest
  } = props;
  const commonProps = {
    id: base.fieldId,
    required: base.required,
    disabled: base.disabled,
    ...base.ariaConfig,
    className: base.fieldClassName,
  };

  const inputProps = {
    ...( rest as any ),
    ...commonProps,
    type: type as any,
    ref: ref,
  };

  if ( base.hasInputGroup ) {
    return (
      <InputGroup className={ base.fieldClassName }>
        { renderAddon( base.prefix, base.prefixAlign || 'inline-start' ) }
        <InputGroupInput { ...inputProps } />
        { renderAddon( base.suffix, base.suffixAlign || 'inline-end' ) }
      </InputGroup>
    );
  }

  return <Input { ...inputProps } />;
};

export const RenderDate = ( {
  props,
  base,
  ref
}: {
  props: InputFieldProps;
  base: BaseRendererProps;
  ref?: ForwardedRef<HTMLInputElement>;
} ) => {
  const {
    label,
    description,
    error,
    errors,
    fieldClassName,
    labelClassName,
    prefix,
    suffix,
    prefixAlign,
    suffixAlign,
    headerExtra,
    className,
    value,
    onChange,
    onBlur,
    placeholder,
    ...rest
  } = props;

  const commonProps = {
    id: base.fieldId,
    required: base.required,
    disabled: base.disabled,
    ...base.ariaConfig,
    className: base.fieldClassName,
  };

  const handleChange = ( dateString: string ) => {
    if ( onChange ) {
      // Create a synthetic event for compatibility
      const syntheticEvent = {
        target: { value: dateString },
        currentTarget: { value: dateString },
      } as React.ChangeEvent<HTMLInputElement>;
      onChange( syntheticEvent );
    }
  };

  return (
    <CalendarInput
      { ...commonProps }
      value={ value as string || "" }
      onChange={ handleChange }
      onBlur={ onBlur as any }
      placeholder={ placeholder }
    />
  );
};

export const RenderTextarea = ( {
  props,
  base,
  ref
}: {
  props: TextareaFieldProps;
  base: BaseRendererProps;
  ref?: ForwardedRef<HTMLTextAreaElement>;
} ) => {
  const commonProps = {
    id: base.fieldId,
    required: base.required,
    disabled: base.disabled,
    ...base.ariaConfig,
    className: base.fieldClassName,
  };

  // Destructure type out since it's not needed for textarea
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const {
    type: _type,
    label,
    description,
    error,
    errors,
    fieldClassName,
    labelClassName,
    prefix,
    suffix,
    prefixAlign,
    suffixAlign,
    headerExtra,
    className,
    ...restProps
  } = props as any;

  const textareaProps = {
    ...restProps,
    ...commonProps,
    ref: ref,
  };

  if ( base.hasInputGroup ) {
    return (
      <InputGroup className={ base.fieldClassName }>
        { renderAddon( base.prefix, base.prefixAlign || 'inline-start' ) }
        <InputGroupTextarea { ...textareaProps } />
        { renderAddon( base.suffix, base.suffixAlign || 'inline-end' ) }
      </InputGroup>
    );
  }
  return <Textarea { ...textareaProps } />;
};

export const RenderSelect = ( {
  props,
  base
}: {
  props: SelectFieldProps;
  base: BaseRendererProps;
} ) => {
  const { options, children, value, placeholder, onValueChange, defaultValue, name, onBlur } = props;
  const commonProps = {
    id: base.fieldId,
    required: base.required,
    disabled: base.disabled,
    onBlur,
    ...base.ariaConfig,
    className: base.fieldClassName,
  };

  const renderSelectItems = () => {
    if ( options ) {
      return options.map( ( option ) => {
        if ( typeof option === 'string' || typeof option === 'number' ) {
          return (
            <SelectItem key={ option } value={ String( option ) }>
              { option }
            </SelectItem>
          );
        }
        return (
          <SelectItem
            key={ option.value }
            value={ option.value }
            disabled={ option.disabled }
          >
            { option.label }
          </SelectItem>
        );
      } );
    }
    return children;
  };

  const selectedLabel = useMemo( () => {
    if ( !value || !options ) return null;
    const option = options.find( ( opt ) => {
      if ( typeof opt === "object" && opt !== null && "value" in opt ) {
        return opt.value === value;
      }
      return String( opt ) === value;
    } );
    return option ? ( typeof option === "object" && option !== null && "label" in option ? option.label : option ) : null;
  }, [ value, options ] );

  const selectContent = (
    <>
      <SelectTrigger { ...commonProps } className={ cn( base.fieldClassName ) }>
        <SelectValue>{ selectedLabel || placeholder }</SelectValue>
      </SelectTrigger>
      <SelectContent className="vega-form dark">{ renderSelectItems() }</SelectContent>
    </>
  );

  if ( base.hasInputGroup ) {
    return (
      <InputGroup className={ base.fieldClassName }>
        { renderAddon( base.prefix, base.prefixAlign || 'inline-start' ) }
        <Select
          value={ value }
          defaultValue={ defaultValue }
          onValueChange={ onValueChange }
          name={ name }
          disabled={ base.disabled }
          required={ base.required }
        >
          <SuperFieldInputGroupSelect { ...commonProps } className={ cn( base.fieldClassName ) }>
            <SelectValue>{ selectedLabel || placeholder }</SelectValue>
          </SuperFieldInputGroupSelect>
          <SelectContent className="vega-form dark">{ renderSelectItems() }</SelectContent>
        </Select>
        { renderAddon( base.suffix, base.suffixAlign || 'inline-end' ) }
      </InputGroup>
    );
  }

  return (
    <Select
      value={ value }
      defaultValue={ defaultValue }
      onValueChange={ onValueChange }
      name={ name }
      disabled={ base.disabled }
      required={ base.required }
    >
      { selectContent }
    </Select>
  );
};

