"use client";

import { Input } from "@/components/ui/input";
import { AnimatePresence, motion } from "motion/react";
import { useEffect, useRef, useState, ForwardedRef, forwardRef } from "react";
import { cn } from "@/lib/utils";

interface LocationInputProps extends Omit<React.ComponentProps<typeof Input>, 'onChange'> {
  value: string;
  onChange: ( value: string ) => void;
  onLocationSelect?: ( location: any ) => void;
  isInvalid?: boolean;
}

declare global {
  interface Window {
    google: any;
  }
}

// Texas bounds for location restriction
const TEXAS_BOUNDS = {
  south: 25.837377,
  west: -106.645646,
  north: 36.500704,
  east: -93.508292,
};

export const LocationInput = forwardRef<HTMLInputElement, LocationInputProps>( ( {
  value,
  onChange,
  onBlur,
  placeholder = "Enter location",
  className,
  name,
  isInvalid,
  onLocationSelect,
  ...props
}, ref ) => {
  const [ inputValue, setInputValue ] = useState( value || "" );
  const [ predictions, setPredictions ] = useState<any[]>( [] );
  const [ isOpen, setIsOpen ] = useState( false );
  const [ highlightedIndex, setHighlightedIndex ] = useState( -1 );

  const innerInputRef = useRef<HTMLInputElement>( null );
  const containerRef = useRef<HTMLDivElement>( null );
  const sessionToken = useRef<any | null>( null );
  const autocompleteService = useRef<any>( null );

  // Sync external value changes
  useEffect( () => {
    setInputValue( value || "" );
  }, [ value ] );

  // Initialize Google Maps Places service
  useEffect( () => {
    let attempts = 0;

    const initService = async () => {
      if ( typeof window === 'undefined' || !window.google ) return;

      try {
        const { AutocompleteSessionToken, AutocompleteSuggestion } =
          await window.google.maps.importLibrary( "places" ) as any;

        sessionToken.current = new AutocompleteSessionToken();
        autocompleteService.current = AutocompleteSuggestion;

      } catch ( error ) {
        console.error( "Error loading Google Maps Places Library", error );
        if ( attempts < 5 ) {
          attempts++;
          setTimeout( initService, 500 );
        }
      }
    };

    initService();
  }, [] );

  // Handle outside click to close dropdown
  useEffect( () => {
    const handleClickOutside = ( event: MouseEvent ) => {
      if ( containerRef.current && !containerRef.current.contains( event.target as Node ) ) {
        setIsOpen( false );
      }
    };

    document.addEventListener( "mousedown", handleClickOutside );
    return () => document.removeEventListener( "mousedown", handleClickOutside );
  }, [] );

  const handleInputChange = async ( e: React.ChangeEvent<HTMLInputElement> ) => {
    const val = e.target.value;
    setInputValue( val );
    onChange( val );

    if ( !val ) {
      setPredictions( [] );
      setIsOpen( false );
      return;
    }

    if ( autocompleteService.current ) {
      try {
        const texasBounds = new window.google.maps.LatLngBounds(
          new window.google.maps.LatLng( TEXAS_BOUNDS.south, TEXAS_BOUNDS.west ),
          new window.google.maps.LatLng( TEXAS_BOUNDS.north, TEXAS_BOUNDS.east )
        );

        const request = {
          input: val,
          sessionToken: sessionToken.current,
          locationRestriction: texasBounds,
        };

        const { suggestions } = await autocompleteService.current.fetchAutocompleteSuggestions( request );

        if ( suggestions && suggestions.length > 0 ) {
          setPredictions( suggestions );
          setIsOpen( true );
        } else {
          setPredictions( [] );
          setIsOpen( false );
        }

      } catch ( error ) {
        console.error( "Error fetching suggestions", error );
        setPredictions( [] );
      }
    }
  };

  const handlePredictionSelect = async ( suggestion: any ) => {
    const text = suggestion.description || suggestion.placePrediction?.text?.toString();

    if ( text ) {
      setInputValue( text );
      onChange( text );

      if ( onLocationSelect && suggestion.placePrediction ) {
        const place = suggestion.placePrediction.toPlace();
        await place.fetchFields( { fields: [ "displayName", "formattedAddress", "location" ] } );
        onLocationSelect( place );
      }
    }
    setIsOpen( false );
    setHighlightedIndex( -1 );
  };

  const handleKeyDown = ( e: React.KeyboardEvent<HTMLInputElement> ) => {
    if ( !isOpen || predictions.length === 0 ) return;

    switch ( e.key ) {
      case "ArrowDown":
        e.preventDefault();
        setHighlightedIndex( ( prev ) => ( prev < predictions.length - 1 ? prev + 1 : 0 ) );
        break;
      case "ArrowUp":
        e.preventDefault();
        setHighlightedIndex( ( prev ) => ( prev > 0 ? prev - 1 : predictions.length - 1 ) );
        break;
      case "Enter":
        e.preventDefault();
        if ( highlightedIndex >= 0 && highlightedIndex < predictions.length ) {
          handlePredictionSelect( predictions[ highlightedIndex ] );
        }
        break;
      case "Escape":
        setIsOpen( false );
        setHighlightedIndex( -1 );
        break;
    }
  };

  return (
    <div className="relative w-full" ref={ containerRef }>
      <Input
        ref={ ref || innerInputRef }
        id={ name }
        name={ name }
        value={ inputValue }
        onBlur={ onBlur }
        onChange={ handleInputChange }
        onKeyDown={ handleKeyDown }
        placeholder={ placeholder }
        className={ className }
        aria-invalid={ isInvalid }
        autoComplete="off"
        { ...props }
      />

      <AnimatePresence>
        { isOpen && predictions.length > 0 && (
          <motion.div
            initial={ { opacity: 0, y: -10 } }
            animate={ { opacity: 1, y: 0 } }
            exit={ { opacity: 0, y: -10 } }
            className="absolute z-50 mt-1 max-h-60 w-full overflow-y-auto rounded-md border bg-popover text-popover-foreground shadow-md"
          >
            <ul className="py-1">
              { predictions.map( ( suggestion, index ) => (
                <li
                  key={ suggestion.place_id || index }
                  onClick={ () => handlePredictionSelect( suggestion ) }
                  className={ cn(
                    "cursor-pointer px-3 py-2 text-sm outline-none transition-colors",
                    index === highlightedIndex
                      ? "bg-accent text-accent-foreground"
                      : "text-popover-foreground hover:bg-accent hover:text-accent-foreground"
                  ) }
                  onMouseEnter={ () => setHighlightedIndex( index ) }
                >
                  { suggestion.description || ( suggestion as any ).placePrediction?.text?.toString() }
                </li>
              ) ) }
            </ul>
          </motion.div>
        ) }
      </AnimatePresence>
    </div>
  );
} );

LocationInput.displayName = "LocationInput";

import { Combobox, ComboboxChips, ComboboxChip, ComboboxChipsInput, ComboboxContent, ComboboxList, ComboboxItem } from '@/components/ui/combobox';
import { BaseFieldProps, SelectOption } from "./base-types";
import { cn } from "@/lib/utils";
import { useEffect, useRef, useState } from 'react';
import { DndContext, closestCenter, KeyboardSensor, PointerSensor, useSensor, useSensors, DragEndEvent } from '@dnd-kit/core';
import { arrayMove, SortableContext, sortableKeyboardCoordinates, horizontalListSortingStrategy, useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

export interface MultiSelectInputProps {
  id?: string;
  value?: string[];
  onValueChange?: ( value: string[] ) => void;
  options: SelectOption[];
  placeholder?: string;
  disabled?: boolean;
  className?: string;
  required?: boolean;
  allowCustom?: boolean;
}

export interface MultiSelectFieldProps extends BaseFieldProps, Omit<MultiSelectInputProps, keyof BaseFieldProps> {
  type: 'multi-select';
}

function SortableChip( { id, children }: { id: string; children: React.ReactNode; } ) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
  } = useSortable( { id } );

  const style = {
    transform: CSS.Transform.toString( transform ),
    transition,
  };

  return (
    <div ref={ setNodeRef } style={ style } { ...attributes } { ...listeners }>
      { children }
    </div>
  );
}

export const MultiSelectInput = ( {
  id,
  value = [],
  onValueChange,
  options,
  placeholder,
  disabled,
  className,
  required,
  allowCustom
}: MultiSelectInputProps ) => {
  const ref = useRef<HTMLDivElement>( null );
  const [ width, setWidth ] = useState( 0 );
  const [ inputValue, setInputValue ] = useState( "" );

  const sensors = useSensors(
    useSensor( PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    } ),
    useSensor( KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    } )
  );

  useEffect( () => {
    if ( ref.current ) {
      setWidth( ref.current.offsetWidth );
    }
  }, [ ref ] );

  const filteredOptions = options.filter( ( option ) => {
    const label = typeof option === 'object' && option !== null && 'label' in option ? option.label : String( option );
    const labelStr = ( typeof label === 'string' || typeof label === 'number' ) ? String( label ) : '';
    return labelStr.toLowerCase().includes( inputValue.toLowerCase() );
  } );

  const showCustomOption = allowCustom && inputValue.length > 0 && !options.some( opt => {
    const val = typeof opt === 'object' && opt !== null && 'value' in opt ? opt.value : String( opt );
    const label = typeof opt === 'object' && opt !== null && 'label' in opt ? opt.label : String( opt );
    const labelStr = ( typeof label === 'string' || typeof label === 'number' ) ? String( label ) : '';
    return val.toLowerCase() === inputValue.toLowerCase() || labelStr.toLowerCase() === inputValue.toLowerCase();
  } );

  const handleDragEnd = ( event: DragEndEvent ) => {
    const { active, over } = event;

    if ( active.id !== over?.id ) {
      const oldIndex = value.indexOf( active.id as string );
      const newIndex = value.indexOf( over?.id as string );

      if ( oldIndex !== -1 && newIndex !== -1 ) {
        onValueChange?.( arrayMove( value, oldIndex, newIndex ) );
      }
    }
  };

  return (
    <div ref={ ref }>
      <Combobox
        value={ value }
        onValueChange={ ( val ) => {
          onValueChange?.( val as string[] );
          setInputValue( "" );
        } }
        multiple
        inputValue={ inputValue }
        onInputValueChange={ setInputValue }
      >
        <DndContext
          sensors={ sensors }
          collisionDetection={ closestCenter }
          onDragEnd={ handleDragEnd }
        >
          <ComboboxChips className={ cn( className ) }>
            <SortableContext items={ value } strategy={ horizontalListSortingStrategy }>
              { value.map( ( val ) => {
                // Find label from options
                const option = options.find( opt => {
                  if ( typeof opt === 'object' && opt !== null && 'value' in opt ) {
                    return opt.value === val;
                  }
                  return String( opt ) === val;
                } );
                const label = option
                  ? ( typeof option === 'object' && 'label' in option ? option.label : option )
                  : val;

                return (
                  <SortableChip key={ val } id={ val }>
                    <ComboboxChip>
                      { label }
                    </ComboboxChip>
                  </SortableChip>
                );
              } ) }
            </SortableContext>
            <ComboboxChipsInput
              placeholder={ value.length === 0 ? ( placeholder || "Select..." ) : undefined }
              id={ id }
              required={ required }
              disabled={ disabled }
              onKeyDown={ ( e ) => {
                if ( e.key === 'Enter' || ( allowCustom && e.key === ',' ) ) {
                  e.preventDefault();
                  e.stopPropagation();

                  if ( allowCustom && inputValue.trim().length > 0 ) {
                    const newValue = inputValue.trim();
                    if ( !value.includes( newValue ) ) {
                      onValueChange?.( [ ...value, newValue ] );
                    }
                    setInputValue( "" );
                  }
                }
              } }
            />
          </ComboboxChips>
        </DndContext>
        <ComboboxContent className={ cn( 'min-w-(--anchor-width) w-(--anchor-width)' ) } style={ { 'width': `${ width }px`, } } sideOffset={ 16 } align="end" alignOffset={ -10 }>
          <ComboboxList>
            { filteredOptions.length === 0 && !showCustomOption && (
              <div className="py-6 text-center text-sm text-muted-foreground">
                No results found.
              </div>
            ) }
            { filteredOptions.map( ( option ) => {
              const optValue = typeof option === 'object' && option !== null && 'value' in option ? option.value : String( option );
              const optLabel = typeof option === 'object' && option !== null && 'label' in option ? option.label : String( option );
              const optDisabled = typeof option === 'object' && option !== null && 'disabled' in option ? option.disabled : false;

              return (
                <ComboboxItem key={ optValue } value={ optValue as string } disabled={ optDisabled } className={ 'capitalize' }>
                  { optLabel }
                </ComboboxItem>
              );
            } ) }
            { showCustomOption && (
              <ComboboxItem key="__custom__" value={ inputValue }>
                Create "{ inputValue }"
              </ComboboxItem>
            ) }
          </ComboboxList>
        </ComboboxContent>
      </Combobox>
    </div>
  );
};

import { useEffect, useRef, useState } from "react";
