export const SearchableSelect = ( {
  id,
  value,
  onValueChange,
  options,
  placeholder,
  disabled,
  className,
  required
}: SearchableSelectProps ) => {
  const [ open, setOpen ] = useState( false );
  const [ width, setWidth ] = useState( 0 );
  const triggerRef = useRef<HTMLButtonElement>( null );

  const selectedOption = options.find( ( option ) => {
    if ( typeof option === 'object' && option !== null && 'value' in option ) {
      return option.value === value;
    }
    return String( option ) === value;
  } );

  const selectedLabel = selectedOption
    ? ( typeof selectedOption === 'object' && 'label' in selectedOption ? selectedOption.label : selectedOption )
    : null;

  // Update width before opening or on window resize
  useEffect( () => {
    if ( open && triggerRef.current ) {
      setWidth( triggerRef.current.offsetWidth );
    }
  }, [ open ] );

  // Also handle resize to keep it responsive
  useEffect( () => {
    const handleResize = () => {
      if ( triggerRef.current ) {
        setWidth( triggerRef.current.offsetWidth );
      }
    };
    window.addEventListener( 'resize', handleResize );
    return () => window.removeEventListener( 'resize', handleResize );
  }, [] );


  return (
    <Popover open={ open } onOpenChange={ setOpen }>
      <PopoverTrigger
        ref={ triggerRef }
        id={ id }
        aria-expanded={ open }
        className={ cn(
          "border-input data-placeholder:text-muted-foreground dark:bg-input/30 dark:hover:bg-input/50 focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 gap-1.5 rounded-md border bg-transparent py-2 pr-2 pl-2.5 text-sm shadow-xs transition-[color,box-shadow] focus-visible:ring-[3px] aria-invalid:ring-[3px] h-9 [&_svg:not([class*='size-'])]:size-4 flex w-full items-center justify-between whitespace-nowrap outline-none disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0",
          !value && "text-muted-foreground",
          className
        ) }
        disabled={ disabled }
      >
        <span className="flex flex-1 text-left line-clamp-1">
          { selectedLabel || placeholder || "Select..." }
        </span>
        <HugeiconsIcon icon={ UnfoldMoreIcon } strokeWidth={ 2 } className="text-muted-foreground size-4 pointer-events-none" />
      </PopoverTrigger>
      <PopoverContent
        className="vega-form dark bg-popover text-popover-foreground data-open:animate-in data-closed:animate-out data-closed:fade-out-0 data-open:fade-in-0 data-closed:zoom-out-95 data-open:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/10 min-w-36 rounded-md shadow-md ring-1 duration-100 p-0"
        align="start"
        style={ { width: width ? `${ width }px` : undefined } }
      >
        <Command>
          <CommandInput placeholder={ placeholder || "Search..." } className="h-9" />
          <CommandList>
            <CommandEmpty>No results found.</CommandEmpty>
            <CommandGroup className="w-full">
              { options.map( ( option ) => {
                const optValue = typeof option === 'object' && option !== null && 'value' in option ? option.value : String( option );
                const optLabel = typeof option === 'object' && option !== null && 'label' in option ? option.label : String( option );
                const optDisabled = typeof option === 'object' && option !== null && 'disabled' in option ? option.disabled : false;

                return (
                  <CommandItem
                    key={ optValue }
                    value={ optLabel as string }
                    onSelect={ () => {
                      onValueChange?.( optValue );
                      setOpen( false );
                    } }
                    disabled={ optDisabled }
                    className="relative flex cursor-default select-none items-center rounded-sm bg-zinc-900 py-1.5 pl-2 pr-8 text-sm text-zinc-100 outline-none transition-colors hover:!bg-zinc-700 hover:!text-zinc-50 data-selected:!bg-zinc-700 data-selected:!text-zinc-50 data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50"
                  >
                    <span className="line-clamp-1">{ optLabel }</span>
                    { value === optValue && (
                      <span className="absolute right-2 flex h-3.5 w-3.5 items-center justify-center">
                        <HugeiconsIcon
                          icon={ Tick02Icon }
                          strokeWidth={ 2 }
                          className="h-4 w-4"
                        />
                      </span>
                    ) }
                  </CommandItem>
                );
              } ) }
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
};

import { AriaAttributes, KeyboardEvent, useEffect, useRef, useState, WheelEvent } from "react";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";
import { BaseFieldProps } from "./base-types";

export interface TagsInputProps {
  id?: string;
  value?: string[];
  onChange?: ( value: string[] ) => void;
  onBlur?: () => void;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
  ariaConfig?: AriaAttributes;
  size?: 'default' | 'sm' | 'lg';
  expand?: boolean;
}

export interface TagsFieldProps extends BaseFieldProps, Omit<TagsInputProps, keyof BaseFieldProps> {
  type: 'tags';
}

export const TagsInput = ( { id, value = [], onChange, onBlur, placeholder, disabled, className, ariaConfig, size = 'default', expand = true }: TagsInputProps ) => {
  const [ inputValue, setInputValue ] = useState( "" );
  const inputRef = useRef<HTMLInputElement>( null );
  const containerRef = useRef<HTMLDivElement>( null );

  const handleKeyDown = ( e: KeyboardEvent<HTMLInputElement> ) => {
    if ( ( e.key === 'Enter' || e.key === ',' ) ) {
      e.preventDefault();
      const trimmed = inputValue.trim().replace( /,/g, '' );
      if ( trimmed ) {
        if ( !value?.includes( trimmed ) ) {
          onChange?.( [ ...( value || [] ), trimmed ] );
        }
        setInputValue( "" );
      }
    } else if ( e.key === 'Backspace' && !inputValue && ( value?.length || 0 ) > 0 ) {
      onChange?.( ( value || [] ).slice( 0, -1 ) );
      e.preventDefault();
    }
  };

  const removeKeyword = ( index: number ) => {
    onChange?.( ( value || [] ).filter( ( _, i ) => i !== index ) );
  };

  const handleBlur = () => {
    const trimmed = inputValue.trim().replace( /,/g, '' );
    if ( trimmed ) {
      if ( !value?.includes( trimmed ) ) {
        onChange?.( [ ...( value || [] ), trimmed ] );
      }
      setInputValue( "" );
    }
    onBlur?.();
  };

  const handleWheel = ( e: WheelEvent ) => {
    if ( !expand && containerRef.current ) {
      containerRef.current.scrollLeft += e.deltaY;
    }
  };

  useEffect( () => {
    if ( !expand && containerRef.current ) {
      // Scroll to the end when input changes or tags are added/removed
      containerRef.current.scrollLeft = containerRef.current.scrollWidth;
    }
  }, [ inputValue, value, expand ] );

  const sizeClasses = {
    sm: "min-h-[32px] text-xs px-2 py-0.5",
    default: "min-h-[36px] text-sm px-2.5 py-1",
    lg: "min-h-[44px] text-base px-3 py-1.5",
  };

  const tagSizeClasses = {
    sm: "px-1.5 py-0 text-[10px]",
    default: "px-2 py-0.5 text-xs",
    lg: "px-2.5 py-1 text-sm",
  };

  const currentSize = sizeClasses[ size ] || sizeClasses.default;
  const currentTagSize = tagSizeClasses[ size ] || tagSizeClasses.default;

  return (
    <div
      ref={ containerRef }
      className={ cn(
        "flex items-center gap-1.5 rounded-md border border-input bg-transparent ring-offset-background cursor-text shadow-xs transition-[color,box-shadow]",
        "focus-within:ring-[3px] focus-within:ring-ring/50 focus-within:border-ring",
        "aria-invalid:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:aria-invalid:border-destructive/50",
        expand ? "flex-wrap" : "flex-nowrap overflow-x-auto no-scrollbar scroll-smooth pr-10",
        currentSize,
        className
      ) }
      onClick={ () => inputRef.current?.focus() }
      onWheel={ handleWheel }
      { ...ariaConfig }
    >
      { ( value || [] ).map( ( keyword, i ) => (
        <span key={ i } className={ cn( "inline-flex items-center gap-1 rounded font-normal bg-secondary text-secondary-foreground border border-border/50 shrink-0", currentTagSize ) }>
          { keyword }
          <button
            type="button"
            onClick={ ( e ) => { e.stopPropagation(); removeKeyword( i ); } }
            className="hover:text-foreground text-muted-foreground transition-colors"
            disabled={ disabled }
          >
            <X className="w-3 h-3" />
          </button>
        </span>
      ) ) }
      <input
        id={ id }
        ref={ inputRef }
        type="text"
        className="flex-1 bg-transparent border-none outline-none min-w-[80px] placeholder:text-muted-foreground"
        placeholder={ ( value || [] ).length === 0 ? ( placeholder || "Enter tags..." ) : "" }
        value={ inputValue }
        onChange={ ( e ) => setInputValue( e.target.value ) }
        onKeyDown={ handleKeyDown }
        onBlur={ handleBlur }
        disabled={ disabled }
      />
    </div>
  );
};

